package com.bank.spark.model;

import java.util.List;

// Row counts per partition, before and after a filter.
public class PartitionStats {
    private final List<Integer> rowsPerPartition;

    public PartitionStats(List<Integer> rowsPerPartition) {
        this.rowsPerPartition = rowsPerPartition;
    }

    public int partitionCount() { return rowsPerPartition.size(); }

    public long totalRows() {
        return rowsPerPartition.stream().mapToLong(Integer::intValue).sum();
    }

    public long emptyPartitions() {
        return rowsPerPartition.stream().filter(r -> r == 0).count();
    }

    public List<Integer> getRowsPerPartition() { return rowsPerPartition; }
}
