package com.bank.spark.service;

import com.bank.spark.model.PartitionStats;

// Advises repartition (rebalance) or coalesce (shrink files).
public class RebalanceAdvisor {

    // After a filter: if most partitions are empty, recommend a repartition count.
    public int recommendRepartitionAfterFilter(PartitionStats afterFilter) {
        long surviving = afterFilter.partitionCount() - afterFilter.emptyPartitions();
        long rows = afterFilter.totalRows();
        // Aim for a small, balanced count proportional to surviving data.
        int target = (int) Math.max(1, Math.min(surviving, rows / 100 + 1));
        return target;
    }

    // Before write: target file count so files are not tiny.
    public int recommendCoalesceBeforeWrite(long totalRows, int rowsPerFileTarget) {
        return (int) Math.max(1, totalRows / rowsPerFileTarget);
    }
}
