package com.bank.spark;

import com.bank.spark.model.PartitionStats;
import com.bank.spark.service.RebalanceAdvisor;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class FraudPartitionDemo {

    private static final Logger log = Logger.getLogger(FraudPartitionDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        RebalanceAdvisor advisor = new RebalanceAdvisor();

        // 200 partitions before the filter — simulate occupancy after a selective fraud filter.
        List<Integer> after = new ArrayList<>();
        for (int i = 0; i < 200; i++) after.add(0); // start all empty
        after.set(7, 180);   // one partition kept 180 survivors
        after.set(42, 95);   // another kept 95
        after.set(150, 25);  // another kept 25
        PartitionStats afterFilter = new PartitionStats(after);

        log.warning(() -> "After fraud filter: " + afterFilter.partitionCount()
                + " partitions, " + afterFilter.emptyPartitions() + " empty, "
                + afterFilter.totalRows() + " surviving rows");

        int repartTarget = advisor.recommendRepartitionAfterFilter(afterFilter);
        log.info(() -> "Recommend repartition(" + repartTarget + ") to rebalance survivors for the enrichment join");

        long alerts = afterFilter.totalRows();
        int coalesceTarget = advisor.recommendCoalesceBeforeWrite(alerts, 1000);
        log.info(() -> "Recommend coalesce(" + coalesceTarget + ") before write to avoid tiny files ("
                + alerts + " alerts, ~1000 rows/file)");

        log.info("Flow: filter -> repartition(rebalance) -> enrich join -> coalesce -> write");
    }
}

